     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * A resting player over `book` — nothing playing, nothing skipped.
     */
    constructor(`book`: FfiBook) :
        this(UniffiWithHandle, 
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_taletrek_ffi_fn_constructor_trekplayer_new(
    
        
        FfiConverterTypeFfiBook.lower(`book`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_taletrek_ffi_fn_free_trekplayer(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_taletrek_ffi_fn_clone_trekplayer(handle, status)
        }
    }

    
    /**
     * The durable position right now — `None` at idle (a resting or
     * finished book has nowhere to resume).
     */override fun `position`(): FfiPosition? {
            return FfiConverterOptionalTypeFfiPosition.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_taletrek_ffi_fn_method_trekplayer_position(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The renderable state right now.
     */override fun `stateSnapshot`(): FfiStateSnapshot {
            return FfiConverterTypeFfiStateSnapshot.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_taletrek_ffi_fn_method_trekplayer_state_snapshot(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * One pure transition: apply `event`, get back what to do.
     */override fun `tick`(`event`: FfiPlayerEvent): FfiPlayerAction {
            return FfiConverterTypeFfiPlayerAction.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_taletrek_ffi_fn_method_trekplayer_tick(
        it,
        
        FfiConverterTypeFfiPlayerEvent.lower(`event`),_status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
    /**
     * A player restored at `position`: paused at the saved paragraph
     * with a fresh failure log (a resume is a new session, never an
     * auto-play). A position whose paragraph does not validate against
     * the book seeds fresh idle — no phantom resume.
     */ fun `restore`(`book`: FfiBook, `position`: FfiPosition): TrekPlayer {
            return FfiConverterTypeTrekPlayer.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_taletrek_ffi_fn_constructor_trekplayer_restore(
    
        
        FfiConverterTypeFfiBook.lower(`book`),
        FfiConverterTypeFfiPosition.lower(`position`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeTrekPlayer: FfiConverter<TrekPlayer, Long> {
    override fun lower(value: TrekPlayer): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): TrekPlayer {
        return TrekPlayer(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): TrekPlayer {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TrekPlayer) = 8UL

    override fun write(value: TrekPlayer, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



