        is FfiPlayerEvent.NextParagraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiPlayerEvent.PrevParagraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiPlayerEvent.NextChapter -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiPlayerEvent.PrevChapter -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiPlayerEvent.SeekToParagraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiParagraphPos.allocationSize(value.`pos`)
            )
        }
        is FfiPlayerEvent.SeekWithinParagraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`offset`)
            )
        }
        is FfiPlayerEvent.SegmentDrained -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
            )
        }
        is FfiPlayerEvent.SegmentFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
                + FfiConverterString.allocationSize(value.`error`)
            )
        }
    }

    override fun write(value: FfiPlayerEvent, buf: ByteBuffer) {
        when(value) {
            is FfiPlayerEvent.Play -> {
                buf.putInt(1)
                Unit
            }
            is FfiPlayerEvent.Pause -> {
                buf.putInt(2)
                Unit
            }
            is FfiPlayerEvent.NextParagraph -> {
                buf.putInt(3)
                Unit
            }
            is FfiPlayerEvent.PrevParagraph -> {
                buf.putInt(4)
                Unit
            }
            is FfiPlayerEvent.NextChapter -> {
                buf.putInt(5)
                Unit
            }
            is FfiPlayerEvent.PrevChapter -> {
                buf.putInt(6)
                Unit
            }
            is FfiPlayerEvent.SeekToParagraph -> {
                buf.putInt(7)
                FfiConverterTypeFfiParagraphPos.write(value.`pos`, buf)
                Unit
            }
            is FfiPlayerEvent.SeekWithinParagraph -> {
                buf.putInt(8)
                FfiConverterDouble.write(value.`offset`, buf)
                Unit
            }
            is FfiPlayerEvent.SegmentDrained -> {
                buf.putInt(9)
                FfiConverterString.write(value.`key`, buf)
                Unit
            }
            is FfiPlayerEvent.SegmentFailed -> {
                buf.putInt(10)
                FfiConverterString.write(value.`key`, buf)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Where playback is — always paired with the snapshot's para/offset.
 */

enum class FfiPlayerStatus {
    
    /**
     * Not playing: before the first `Play` and after the book ends.
     */
    IDLE,
    /**
     * Playing the current paragraph's segment.
     */
    PLAYING,
    /**
     * Suspended at the current paragraph.
     */
    PAUSED;

    


    companion object
}


